# November 20, 2026: Summerside, Prince Edward Island. Region pe drawn by tools/choose.py --claim with --state limited to
# the eastern provinces; Summerside had nothing on the map but the Indian Head light (pe_tpau's note listed it as a lead).
# Sources opened in this session: the Canadian Register of Historic Places statement for each place (historicplaces.ca,
# read with tools/page.py --all; ids from the {{HPC row}} templates of Wikipedia's "List of historic places in Summerside,
# Prince Edward Island"); Culture Summerside's pages (the city's heritage department: museum hours and histories); Tourism
# PEI; the Parish of St. Mary & St. John's worship page; the Atlantic Baptist Built Heritage Project; HMdb marker 141017;
# CBC News (2017) on the old station; OpenStreetMap (tools/nom.py) for some positions.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
def CS(t,p): return ['Culture Summerside: '+t,'https://www.culturesummerside.com/'+p]
BATCH={'key':'pe_eawz','label':'Summerside, Prince Edward Island','added':'2026-11-20 03:12'}
GLANCE=CS('Museums & Sites at a Glance','copy-of-what-s-on')
ANGL=L('Parish of St. Mary & St. John, Summerside: What to expect (service times)','https://wisteria-gerbil-4mm7.squarespace.com/worship')
PLACES=[
N('summerside-city-hall','Summerside City Hall (Former Summerside Post Office)','Summerside','pe','civic','standing',46.3931,-63.7907,'exact','view','walk','','1884–1886',
  'A Romanesque Revival post office and customs house of brick and sandstone, designed by Thomas Fuller, the Dominion\'s Chief Architect, and built for the federal government in the mid-1880s (the federal statement gives 1883 to 1887, the city\'s 1884 to 1886). A clock tower was added in 1915. The post office moved out in 1953 and sold the building to the town, which made it the town offices after the old town hall burned in 1955; it survived an attempt to pull it down, was extended east along Fitzroy Street in 2003, and is now City Hall. A national historic site since 1983.',
  'Red brick with sandstone string courses and lintels, compound arches over the entrances, a cushion capital by the southwest door, the one-storey customs wing on the south side, copper eavestroughs, and the 1915 clock tower with its four original faces and original works (Register). Over the Summer Street entrance a carving shows a pig\'s head among doves, said to be the work of a disgruntled sculptor; the panelled doors on Summer Street carry local scenes (Register). Interior not checked.',
  'Find the pig among the doves over the door.',
  'City-owned, corner of Summer and Fitzroy streets, downtown; street parking. Seen from the street any time; office hours not checked.',
  [HP('Former Summerside Post Office National Historic Site',7418),HP('Summerside City Hall',2753)],brick='yes'),
N('summerside-armoury','Summerside Armoury (Summerside Interpretive Centre and PEI Fox Museum)','Summerside','pe','civic','standing',46.3928,-63.79064,'exact','open','walk','','1911–1912',
  'A two-storey red brick armoury on a raised basement of rusticated stone, built to a standard federal plan in 1911–1912 after the town\'s militia drill shed burned in the Great Fire of 1906. It was the main recruiting centre for Prince County in both world wars. The militia moved out in 1992 and the city took it over; it housed the International Fox Museum from 2005 and, after renovations, opened in summer 2022 as the Summerside Interpretive Centre, with the PEI Fox Museum upstairs.',
  'Red brick with corner buttresses, a round arch over the main troop entrance, stone sills and a stone-trimmed false pediment; inside, the Register names the wood floors, the stairs and the metal roof trusses (Register). Six digital exhibits on Summerside and a museum of the Island\'s silver fox farming industry, which had its world headquarters here (Culture Summerside).',
  'Where the silver fox boom is remembered, in the drill hall.',
  'City-owned, 33 Summer Street across from City Hall. Culture Summerside: open by appointment or as staff are available, call 902-432-1326; admission pay what you can. Summer opening hours not given on the page read.',
  [HP('PEIR Armoury',11247),CS('Summerside Interpretive Centre','copy-of-the-pei-fox-museum'),CS('PEI Fox Museum','the-international-fox-museum')],
  brick='yes',hours='By appointment or as staff are available (902-432-1326); pay what you can'),
N('summerside-law-courts','Summerside Law Courts (Prince County Courthouse)','Summerside','pe','civic','standing',46.3956,-63.7918,'exact','view','walk','','1873–1874',
  'A red brick Italianate courthouse, built in 1873, the year the Island joined Confederation, when Summerside replaced nearby St. Eleanors as the seat of Prince County. It was designed by John Corbett and built by Thomas Beattie, who also built the Indian Head lighthouse, and held both the court and the gaol. William Henry Pope, a Father of Confederation, was its first judge. Gutted by the fire of 1906, it shielded the wooden buildings north of it, was rebuilt, and gained a third storey in the 1930s; it is still a courthouse.',
  'A symmetrical red brick front with corner quoins, paired round-headed windows and a curved arch over the door, on treed grounds (Register). The original mansard roof with iron cresting and a belvedere is long gone (Register). A working courthouse; interior not checked.',
  '',
  'Provincial courthouse, 108 Central Street; street parking. Seen from the street.',
  [HP('Summerside Law Courts',1629)],brick='yes'),
N('wyatt-house-summerside','Wyatt Historic House Museum','Summerside','pe','landmark','standing',46.39445,-63.78896,'exact','open','walk','','1867',
  'A pale yellow wooden house built in 1867 for the merchant Robert Alder Strong and bought in 1887 by the shipbuilder John E. Lefurgey, whose daughter Cecelia lived here with her husband Ned Wyatt, Speaker of the Assembly 1912–1916. Three prime ministers, Borden, Meighen and Bennett, were guests. Their daughter Wanda Wyatt, the first woman in PEI to study law and founder of the Wyatt Foundation, lived here until her death in 1998 at 102, and the house became a museum of the family and the town.',
  'A Georgian gable-front house with Greek Revival returned eaves, a Gothic dormer, Queen Anne paired bay windows, and 1928 additions: Palladian attic windows, a six-panel door and a Doric porch with fanlight (Register). Inside, the family\'s furniture and collections, shown on an hour-long guided tour; pine floors from ships\' masts (Culture Summerside).',
  'A house kept as the family left it, ghosts included.',
  'City museum (Culture Summerside), 85 Spring Street; buy tickets at the Lefurgey Cultural Centre across the yard. Admission $13.50, students and seniors $11.50, family $40 (Culture Summerside). In November 2026 Culture Summerside said the museum was closed for maintenance; off season by appointment, 902-432-1286.',
  [HP('Wyatt Historic House',2612),CS('Wyatt House Museum','copy-of-wyatt-historic-house-museum-1'),GLANCE,L('Tourism PEI: Wyatt House Museum','https://www.tourismpei.com/attractions/wyatt-house-museum')],
  brick='no',hours='June 27 to September 26, select hours after September 1 (Tourism PEI); off season by appointment; closed for maintenance as of November 2026'),
N('lefurgey-cultural-centre','Lefurgey Cultural Centre ("Bonny Castle")','Summerside','pe','landmark','standing',46.3942,-63.7881,'exact','open','walk','','1867',
  'A 23-room Gothic Revival house designed by Matthew Dempsey in 1867 for the carriage builder William Tuplin and bought in 1871 by the shipbuilder and legislator John E. Lefurgey, who embellished it and called it "Bonny Castle". The druggist J. E. Dalton raised it five feet after 1924. Wanda Wyatt bought back her grandparents\' house in 1966 and opened it in 1971 as a crafts centre; the city has owned it since 1998. A fire gutted much of the east side in March 2004, and it reopened after rebuilding in August 2005.',
  'A steep roof, a central gable with ornate bargeboard, and a wrap-around veranda with a vaulted ceiling, under a curved bay window and a small balcony (Register; Culture Summerside). The first floor holds a gift shop, gallery and meeting space; ice cream and rhubarb punch on the veranda in summer (Culture Summerside).',
  'Called the crown jewel of Summerside\'s built heritage.',
  'City-owned (Culture Summerside), 205 Prince Street at Granville Street; tickets for the Wyatt House Museum are sold here. Hours from Culture Summerside\'s page.',
  [HP('Lefurgey Cultural Centre',4102),CS('Lefurgey Cultural Centre','lefurgey-cultural-centre')],
  brick='no',hours='Year-round, Monday to Friday 9 a.m. to 4 p.m.'),
N('macnaught-history-centre','MacNaught History Centre and Archives','Summerside','pe','landmark','standing',46.3941,-63.7891,'exact','open','walk','','1887',
  'A Georgian house with Gothic Revival touches, built in 1887 for the land surveyor John Clay on a lot he bought from the foundry man George Bishop. J. Watson MacNaught, MP, Solicitor General in 1963, bought it in 1957. The Wyatt Foundation acquired it in 1998, and after restoration in 2000 it became the city\'s history centre and archives, the third of the Wyatt Heritage Properties.',
  'Clapboard walls, stacked square bay windows with brackets and scalloped shingles, an enclosed front sunporch with a balustraded balcony above, and a rear Doric veranda (Register). Inside, a research room and a small exhibit: Sir John A. Macdonald\'s gold pocket watch, paintings by John Gothard Baker (Culture Summerside).',
  '',
  'City archives (Culture Summerside), 75 Spring Street; free research room; call 902-432-1332 for an appointment. Hours from Culture Summerside\'s "at a glance" page.',
  [HP('MacNaught House',2611),CS('MacNaught History Centre & Archives','macnaught-history-centre-archives'),GLANCE],
  brick='no',hours='Year-round, Tuesday to Saturday 10 a.m. to 12:30 p.m. and 1:30 to 4 p.m.'),
N('bishops-machine-shop-summerside','Bishop\'s Machine Shop Museum','Summerside','pe','industry','standing',46.39395,-63.78909,'exact','open','walk','','1870s–1980s',
  'A small shingled machine shop, the only survivor of the Bishop foundry complex that George Bishop, a blacksmith\'s son, built on Water Street at Autumn Street after buying the land in 1873; by 1877 it was turning out ploughs. His son Thomas kept the machine shop from 1935, repairing motorboat engines and farm machinery with his son Ralph, the fourth generation, who closed it in the mid-1980s and left it much as it had been. The city bought it after Ralph Bishop died in 1996 and opened it as a museum in 2006.',
  'A turn-of-the-century belt-driven machine shop with its lathes, machining tools and gadgets in place (Culture Summerside). The shop was moved from the waterfront: its own page gives 71 Spring Street, beside the MacNaught History Centre, where OpenStreetMap maps it, while the city\'s "at a glance" page gives 101 Water Street; the pin follows the first.',
  'A belt-driven shop left as the last machinist closed the door.',
  'City museum (Culture Summerside); admission pay what you can. In November 2026 its page said closed for the season, reopening in spring 2027; summer hours not given.',
  [CS('Bishop Machine Shop Museum','bishop-s-machine-shop'),GLANCE],
  conf='mixed',brick='no',hours='Summer season; closed until spring 2027 (times not given)'),
N('holman-homestead-summerside','Holman Homestead and Garden','Summerside','pe','landmark','standing',46.393,-63.7915,'exact','open','walk','','1850s–1880s',
  'A large green Georgian-influenced house that was home for more than a century to the family of R. T. Holman, whose Water Street store became the Holman Department Store, known across the Maritimes. Holman bought the lot in 1870 from a Catholic priest; the house was probably the parish house shown on an 1863 map, and the next lot held the Catholic chapel brought from Indian River in 1853 and used until 1874. The garden, laid out from the 1870s, was called the finest flower garden on the Island in 1879. Carrie Holman, who wrote "Our Island Story", lived here until 1972.',
  'Three sections: two gable-roofed parts and a two-storey Second Empire mansard wing to the east, with round-arched upper windows, heavily bracketed eaves, an oriel window, bay windows and two brick chimneys (Register). Tourism PEI describes an ice cream parlour on the ground floor and three furnished suites above, in "the historic 1854 Holman Homestead"; the Register gives no single building date.',
  'The garden that was the pride of the town.',
  'Private business (ice cream parlour with suites to rent), 286 Fitzroy Street at Summer Street. Tourism PEI lists the suites as open all year; the parlour\'s hours not checked.',
  [HP('Holman Homestead and Garden',16273),L('Tourism PEI: Holman\'s Heritage Suites','https://www.tourismpei.com/where-to-stay/holmans-heritage-suites')],
  brick='some',hours='?'),
N('st-marys-anglican-summerside','St. Mary\'s Anglican Church, Summerside','Summerside','pe','worship','standing',46.394,-63.7911,'exact','open','walk','','1908–1909',
  'The second St. Mary\'s on this corner: the first, of 1861, burned in the Great Fire of 1906 with over a hundred other buildings. The congregation raised money from Anglican parishes across PEI and Nova Scotia, and the local architect George E. Baker drew a brick Gothic church, dedicated on September 12, 1909. Its crenellated tower was taken down for safety in the late 1990s and the bell set in a brick housing on the south side.',
  'Brick trimmed with Island sandstone, faux buttresses with sandstone caps, Gothic windows with tracery (Register). Inside, the 1908 work: an arched ceiling of natural hemlock, ash wainscoting, cypress doors and casings and main arch; the clear windows have been replaced over the years by memorial stained glass (Register).',
  'A hemlock ceiling built after the town burned.',
  'Anglican Parish of St. Mary & St. John, 66 Summer Street at Church Street; street parking. Service times from the parish\'s own page.',
  [HP('St. Mary\'s Anglican Church',11073),ANGL],brick='yes',hours='Sunday 8 a.m. said Eucharist and 10:45 a.m. sung Communion'),
N('st-johns-anglican-st-eleanors','St. John\'s Anglican Church, St. Eleanors','Summerside','pe','worship','standing',46.41973,-63.81058,'exact','open','drive','','1838–1842',
  'The first Church of England congregation on the Island built its church here in 1825, when St. Eleanors was the seat of Prince County; it burned in 1835 and George Tanton Jr., who had built it, put up this one between 1838 and 1842. The cabinet maker Robert Ellis fitted it out in the 1840s with box pews, a gallery and two raised pulpits; the chancel and pews were altered in 1888. The churchyard holds William Henry Pope, a Father of Confederation, his brother Premier James Colledge Pope, and Premier Albert C. Saunders.',
  'A long Gothic Revival frame church with a tall buttressed tower, finials and a ball-topped spire, now clad in white vinyl (1985) that hides the original shingles; a lych gate of 1967 and a walk to the Pope grave at the east end (Register). Inside, the 1840s gallery survives in altered form, with rooms built under and in it in 1950 and 1967 (Register); interior otherwise not checked.',
  'One of the oldest buildings in the city, with a Father of Confederation in the yard.',
  'Anglican Parish of St. Mary & St. John, 62 South Drive, in the old village of St. Eleanors. The churchyard is beside the church. Service time from the parish\'s own page.',
  [HP('St. John\'s Anglican Church',16353),ANGL],brick='no',hours='Sunday 9:15 a.m. Holy Communion'),
N('trinity-united-summerside','Trinity United Church, Summerside','Summerside','pe','worship','standing',46.39463,-63.78961,'exact','view','walk','','1893–1894',
  'A Gothic Revival Methodist church with two towers, designed by George E. Baker and opened on August 12, 1894, with seats for 500; the cornerstone carries both A.D. 1893 and the Masonic date A.L. 5893. Spared by the Great Fire of 1906, it is the oldest church building still in use in the original town. It became Trinity United at church union in 1925, and was lengthened in 1957 and again in 1982 and 2007.',
  'Two towers, white vinyl and decorative cedar shingles outside; inside, every window of the sanctuary is memorial stained glass, the first unveiled in 1938 (Register). Service times not found on a page of the congregation\'s own; interior not checked.',
  '',
  'United Church congregation, 90 Spring Street at Winter Street; street parking. Seen from the street; service times not checked.',
  [HP('Trinity United Church',16183)],brick='no'),
N('summerside-united-baptist','Summerside United Baptist Church','Summerside','pe','worship','standing',46.3936,-63.7892,'exact','view','walk','','1907',
  'The congregation began in 1868; its first church on this corner burned in the Great Fire of 1906. George E. Baker drew the plans for the new one free of charge, and it opened on December 22, 1907, with an Akron-plan interior. Halls were added in 1924 and 1949.',
  'A white frame church with round-arched Romanesque Revival windows, a steep gable roof and a square side tower, wide shingles below and decorative cedar shingles above (Register). The 1907 press described leaded cathedral glass, three rows of circular seats and a panelled ceiling of clear white spruce with cypress and ash finish (Register); whether that survives inside not checked.',
  '',
  'Active Baptist church (Atlantic Baptist Built Heritage Project), 219 Church Street at Spring Street. Seen from the street; service times not checked.',
  [HP('Summerside United Baptist Church',15107),L('Atlantic Baptist Built Heritage Project: Summerside United Baptist Church','https://atlanticbaptistheritage.omeka.net/items/show/206')],brick='no'),
N('the-kirk-summerside','"The Kirk" (former Church of Scotland), Summerside','Summerside','pe','worship','standing',46.3922,-63.7845,'exact','view','walk','','1818?–1889',
  'A small shingled building that served Summerside\'s Church of Scotland adherents, the followers of the Rev. Donald McDonald, for over a century, and gave Kirk Street its name. Its age is disputed: articles of 1928 and 1935 say it was the Pope family\'s house, built in Bedeque in 1818, where Premier James C. Pope and William Henry Pope were born, and hauled across the ice about 1873; a church here was formally opened in February 1889. Services ended in 1996 and it was sold in 1998 and made back into a house.',
  'One and a half storeys, a steep gable facing Kirk Street, cedar shingles and the small vestibule it had as a church (Register). A private house.',
  'Maybe the house two Fathers of the Island were born in, dragged over the ice.',
  'Private house, 138 Kirk Street at Russell Street. View from the street only.',
  [HP('Former Church of Scotland',15642)],conf='mixed',brick='no'),
N('summerside-back-range-light','Summerside Back Range Light','Summerside','pe','light','standing',46.3913,-63.7713,'site','view','drive','','1895',
  'A 19.7-metre square, tapering wooden range light built in 1895 to guide ships into Bedeque Bay: entering past Indian Head, a ship lined up this light with the front range light on the railway wharf to keep to the channel. It was closed in in its present form in 1904; the front light was replaced by a metal tower in 1961.',
  'A white shingled tower with a bracketed platform, a small square red lantern, a red stripe down from the lantern and three windows one above another on the west side (Register). Still an aid to navigation (Register, 2007).',
  '',
  'On Glover\'s Shore Road east of downtown (Register address 14 Glover\'s Shore Road). Seen from the road; owner not checked. Pin from the Register list point, checked on the aerial.',
  [HP('Summerside Back Range Light',10116)],brick='no'),
N('crockett-gallant-building-summerside','Crockett-Gallant Building','Summerside','pe','civic','standing',46.3917,-63.7915,'exact','view','walk','','1919',
  'A two-storey commercial block built in 1919 under the architect George E. Baker for the jeweller Herbert R. Crockett and the druggist J. Edward Gallant, after a fire in December 1916 burned out both sides of Water Street. It had a jewellery store in walnut and a drug store in oak joined by an archway, with nine offices upstairs; the town offices were here in 1955–56 after the town hall burned. The Crocketts kept the jewellery business for three generations and took over the whole ground floor after the pharmacy closed in 1974.',
  'A flat-roofed corner building with a brick front on Water Street, beige vinyl above and an awning wrapping both street sides (Register). A black structural glass and aluminium front was put on after 1949; whether it survives not checked.',
  '',
  'Private commercial building, 281 Water Street at Summer Street. Seen from the street; whether Crockett\'s still trades here not checked.',
  [HP('Crockett-Gallant Building',15441)],brick='some'),
N('bowness-house-summerside','Bowness House ("the stone house")','Summerside','pe','landmark','standing',46.3949,-63.7918,'site','view','walk','','1908',
  'A Four Square house with Queen Anne details, built in 1908 of ballast stones from the sailing ships and schooners that used Summerside harbour, as the retirement home of Robert S. Bowness, one of the town\'s first professional photographers. The architect was J. W. Percy Tanton. Stone is rare on the Island, and the Register counts only three buildings built of ballast stone.',
  'Ballast-stone walls, a stacked bay window on the south side, pediment gables with Palladian windows and medallion bargeboards, and a front sunporch of about 1924 (Register). A private house.',
  'A house built from what the ships threw out.',
  'Private house, 88 Central Street. View from the street only.',
  [HP('Bowness House',2497)],brick='no'),
N('parish-school-summerside','Former Parish School (Massey House)','Summerside','pe','civic','standing',46.3968,-63.7883,'site','view','walk','','1864',
  'Summerside\'s first convent and Catholic school, founded in 1864 by the Rev. James MacDonald and the Sisters of the Congregation of Notre Dame of Montreal; it took Protestants and Catholics, girls and small boys, until a larger building replaced it in 1885. Hugh J. Massey, town clerk for over 30 years, bought half of it and moved it here in 1895 as his house.',
  'A Maritime Vernacular house with an off-centre Gothic front gable and paired round-arched windows, a mix of clapboard, shingles and fish-scale shingles, wooden cornices and paired chimneys (Register). A private house.',
  '',
  'Private house, 153 Spring Street at Pleasant Street. View from the street only.',
  [HP('Parish School',2730)],brick='no'),
N('memorial-square-summerside','Memorial Square and the Drill Shed site','Summerside','pe','landmark','standing',46.3937,-63.7901,'site','public','walk','','1866',
  'The city\'s oldest public park. The colonial government built a wooden militia drill shed here in 1866, one of three on the Island, and the town used it as a skating rink, concert hall and exhibition hall until it burned in the Great Fire of 1906. The town bought the ground in 1908; it was named Dominion Square in 1911 and Memorial Square in 1938, after the Soldier\'s Monument for Prince County\'s dead of the Great War, unveiled in July 1922. The city redesigned it in 2002–2004.',
  'The 1922 cenotaph with a later stone for the Second World War and Korea, a memorial of 2000 to the airmen killed training in PEI under the British Commonwealth Air Training Plan, and an interpretive plaque on the path in from Spring Street at the southeast corner marking the drill shed (Register).',
  '',
  'City park (the town bought it in 1908 and the City of Summerside redesigned it in 2002 to 2004: Register) between Summer and Spring streets, Church to Winter streets; open ground, street parking.',
  [HP('Memorial Square',16330),HP('Site of former Summerside Drill Shed',10065)],brick='?'),
N('summerside-railway-station','Former Summerside Railway Station','Summerside','pe','rail','standing',46.39085,-63.78818,'exact','view','walk','','1927',
  'The CNR station of 1927, planned with the Charlottetown architect C. B. Chappell and the Summerside contractor Percy Tanton, which replaced a three-gabled station that was hauled off to become a canning factory. Coach service ended in 1969 and the last train left the Island in December 1989. A Rotary Club campaign made it the public library from the 1990s; the library moved out in December 2016, and in January 2017 the city offered it for sale with a requirement to keep it in fitting use.',
  'A long building with the hipped roof, wide eaves and big brackets of a station, and murals on the outside walls honouring railway workers (Register; CBC). The rail bed beside it is now the Confederation Trail (HMdb). Present owner and use not checked since 2017.',
  'The only piece of the railway left in town.',
  'Corner of Water and Granville streets (192 Water Street), on the Confederation Trail. Seen from the street and the trail.',
  [HP('192 Water Street (former railway station)',10102),L('HMdb: The Railway Station','https://www.hmdb.org/m.asp?m=141017'),L('CBC News, January 25, 2017: Summerside seeking new vision for historic train station','https://amp.cbc.ca/lite/story/1.3951852')],brick='?'),
]
